INSERT INTO `comentarios` (`id`, `ticket_id`, `usuario_id`, `comentario`, `criado_em`) VALUES
(1, 2, 1, 'adasdsdsasa', '2025-10-29 19:14:51'),
(2, 4, 1, 'Teste de resposta\r\n\r\nDocumento sem título\r\n\r\n	Hugo Alexandre Costa Miranda\r\nAssessor de Infraestrutura e Soluções de Tecnologia da Informação\r\nSetor de TI\r\nhugo.miranda@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n(51) 3334-6799\r\nwww.crprs.org.br\r\n\r\nEm 29/10/2025 16:13, CRPRS Helpdesk escreveu:\r\n> Resposta do Ticket\r\n>\r\n>\r\n>   🎫 Nova Resposta no seu Ticket\r\n>\r\n> Olá *Hugo Miranda*,\r\n>\r\n> Você recebeu uma nova resposta da nossa equipe de suporte:\r\n>\r\n> *Ticket:* #00004\r\n> *Assunto:* TESTE 4\r\n> *Data da Resposta:* 29/10/2025 16:13\r\n>\r\n>\r\n>       📝 Resposta da Equipe:\r\n>\r\n> Olá! Seu ticket foi atribuído ao técnico Hugo Miranda, que analisará \r\n> seu pedido e em breve lhe responderá.\r\n>\r\n> *💡 Como responder:*\r\n>\r\n> Para continuar a conversa, basta responder (reply) a este e-mail. Sua \r\n> resposta será automaticamente adicionada ao ticket.\r\n>\r\n> Atenciosamente,\r\n>\r\n> 	Equipe de Suporte em Tecnologia da Informação\r\n> Setor de TI\r\n> suporte@crprs.org.br\r\n>\r\n> Conselho Regional de Psicologia do Rio Grande do Sul\r\n> Av. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n> (51) 3334-6799\r\n> www.crprs.org.br\r\n>\n\n📎 3 anexo(s) incluído(s) neste comentário.', '2025-10-29 19:22:01'),
(3, 6, 1, 'Comentario Rafael Rueda em 06/10/2025:\r\n\r\n Boa tarde Raquel,\r\npede por gentileza pra ele tentar novamente.\r\nTentei simular o problema mas não consegui, talvez tenha sido alguma instabilidade no BRC.\r\nNão percebi nenhum problema em relação ao cadastro dele no sistema, nem com o usuário.', '2025-10-30 11:42:05'),
(4, 7, 1, 'Comentário de Rafael Rueda - 06/10/2025, 14:14:30\r\n Boa tarde Larissa,\r\nliberei os processos para serem movimentados.\r\nNão encontrei em qual processo o 2741 foi apensado, não estava vinculado a nenhum dos dois (2740 e 2749).\r\nEsse procedimento de apensamento parece ser novo no BRC, mas parece não estar funcionando 100% ainda.', '2025-10-30 11:49:13'),
(5, 8, 1, 'Comentário de Rafael Rueda - 06/10/2025, 14:20:22\r\n Boa tarde Danuza,\r\no boleto foi gerado?\r\nVi que esta paga a taxa de certificado.', '2025-10-30 11:56:31'),
(6, 9, 1, 'Correção do solicitante: Marcia Cristina Silveira de Castro', '2025-10-30 12:08:29'),
(7, 9, 1, 'Comentário de Rafael Rueda - 08/10/2025, 15:03:18\r\nO documento foi alterado após revisão, o termo \"em dia\" ficou fixo.\r\nPrecisamos revidar para saber se voltamos com a regra anterior ou se mantemos dessa forma.', '2025-10-30 12:11:27'),
(8, 10, 3, 'Comentário por Rafael Rueda:\r\n\r\nPrecisamos avaliar a possibilidade dessa mudança, levando em consideração os dados que são utilizados atualmente pelos modelos.\r\nSerá necessário alterar os modelos para que passem a utilizar outra tela, isso pode impactar nos dados que são apresentados hoje.', '2025-10-30 14:02:46'),
(9, 18, 1, 'Rueda,\r\ntu consegues realizar essa finalização em lote ou abrimos chamado para o suporte do BRC?', '2025-10-30 15:06:47'),
(10, 28, 1, 'Prezado:\r\nSolicitamos a inclusão ao CFP nesta data. Assim que nos retornarem, te avisamos.', '2025-10-30 17:23:51'),
(11, 19, 1, 'Permissão concedida!', '2025-10-30 17:27:57'),
(12, 22, 1, 'Prezado:\r\nDados de acesso informados para a Keli.', '2025-10-30 17:33:37'),
(13, 26, 1, 'Prezado:\r\nAs permissões do grupo Financeiro foram importadas para o grupo Finaeceiro+Logistica.', '2025-10-30 17:54:14'),
(14, 30, 1, 'Prezado:\r\nNesta data foi encaminhada solicitação de alteração ao Banco de Preços. Provavelmente eles te encaminharão um e-mail para criação da senha. Solicito a gentileza de nos informar caso receba esse e-mail deles.', '2025-10-30 18:28:49'),
(15, 31, 1, 'Olá Geovana!\r\nVerifiquei a fila da área técnica e teu ramal não está na fila (imagem anexa). É possível que alguém tenha te passado ligações.\r\nObserve se persiste o recebimento de ligações e nos informe, por favor. Por hora vou fechar este chamado. Se precisar, basta responder ao e-mail que o chamado será reaberto.', '2025-10-30 21:20:19'),
