INSERT INTO `comentarios` (`id`, `ticket_id`, `usuario_id`, `comentario`, `criado_em`) VALUES
(131, 79, 1, 'Boa tarde, Guilherme!\r\nSalvo engano, não recebi tua resposta ao e-mail anterior:\r\n\"Não recomendamos a utilização do Thunderbid em dois dispositivos simultaneamente com a mesma conta. Pode ocorrer inconsistências no download das mensagens. Haja vista que o tua conta de e-mail já esta configurada no PC, oferecemos a possibilidade de tu acessares, pelo notebook,  o webmail (diretamente no site do provedor de e-mail). No entanto destacamos que os e-mails lidos no webmail podem não ser baixados no Thunderbird e os emails enviados pelo webmail ficam registrados somente nos enviados do webmail.\r\nDeseja ter acesso ao webmail?\"', '2025-11-14 19:42:41'),
(132, 79, 7, 'Boa tarde!\r\n\r\nPor enquanto não precisa. Caso haja uma necessidade faço a solicitação.\r\n\r\n\r\nAtenciosamente\r\n\r\nDocumento sem título\r\n\r\n	Guilherme Bernst Roesler\r\nCoordenador de Comunicação\r\nguilherme.roesler@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br\r\n\r\nEm 14/11/2025 16:42, Suporte CRPRS escreveu:\r\n> Resposta do Ticket\r\n>\r\n>\r\n>   🎫 Nova Resposta no seu Ticket\r\n>\r\n> Olá *guilherme.roesler*,\r\n>\r\n> Você recebeu uma nova resposta da nossa equipe de suporte:\r\n>\r\n> *Ticket:* #00079\r\n> *Assunto:* ACESSO THUNDERBIRD NOTEBOOK\r\n> *Responsável:* Hugo Miranda\r\n> *Data da Resposta:* 14/11/2025 16:42\r\n>\r\n>\r\n>       📝 Resposta da Equipe:\r\n>\r\n> Boa tarde, Guilherme! Salvo engano, não recebi tua resposta ao e-mail \r\n> anterior: \"Não recomendamos a utilização do Thunderbid em dois \r\n> dispositivos simultaneamente com a mesma conta. Pode ocorrer \r\n> inconsistências no download das mensagens. Haja vista que o tua conta \r\n> de e-mail já esta configurada no PC, oferecemos a possibilidade de tu \r\n> acessares, pelo notebook, o webmail (diretamente no site do provedor \r\n> de e-mail). No entanto destacamos que os e-mails lidos no webmail \r\n> podem não ser baixados no Thunderbird e os emails enviados pelo \r\n> webmail ficam registrados somente nos enviados do webmail. Deseja ter \r\n> acesso ao webmail?\"\r\n>\r\n> *💡 Como responder:*\r\n>\r\n> Para continuar a conversa, basta responder (reply) a este e-mail. Sua \r\n> resposta será automaticamente adicionada ao ticket.\r\n>\r\n> Atenciosamente,\r\n>\r\n> ﻿ Documento sem título\r\n>\r\n> 	Equipe de Suporte em Tecnologia da Informação\r\n> Setor de TI\r\n> suporte@crprs.org.br\r\n>\r\n> Conselho Regional de Psicologia do Rio Grande do Sul\r\n> Av. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n> (51) 3334-6799\r\n> www.crprs.org.br\r\n>', '2025-11-14 19:54:01'),
(133, 184, 24, 'Bom dia,\r\n\r\nRecebemos as denúncias no e-mail *crprs.areatecnica3@gmail.com*\r\n\r\nAt.te\r\n\r\nDocumento sem título\r\n\r\n	Cristina Leite Lucero\r\nAssistente Administrativa\r\nÁrea Técnica\r\ncristina.lucero@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br\r\n\r\nEm 14/11/2025 16:30, Suporte CRPRS escreveu:\r\n> Resposta do Ticket\r\n>\r\n>\r\n>   🎫 Nova Resposta no seu Ticket\r\n>\r\n> Olá *orientec*,\r\n>\r\n> Você recebeu uma nova resposta da nossa equipe de suporte:\r\n>\r\n> *Ticket:* #00184\r\n> *Assunto:* Drive_de_denúncias_com_armazenamento_esgotado\r\n> *Responsável:* Hugo Miranda\r\n> *Data da Resposta:* 14/11/2025 16:30\r\n>\r\n>\r\n>       📝 Resposta da Equipe:\r\n>\r\n> Oi Cristina! Por favor, informe o endereço de e-mail dessa conta de \r\n> denúncia. Grato!\r\n>\r\n> *💡 Como responder:*\r\n>\r\n> Para continuar a conversa, basta responder (reply) a este e-mail. Sua \r\n> resposta será automaticamente adicionada ao ticket.\r\n>\r\n> Atenciosamente,\r\n>\r\n> ﻿ Documento sem título\r\n>\r\n> 	Equipe de Suporte em Tecnologia da Informação\r\n> Setor de TI\r\n> suporte@crprs.org.br\r\n>\r\n> Conselho Regional de Psicologia do Rio Grande do Sul\r\n> Av. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n> (51) 3334-6799\r\n> www.crprs.org.br\r\n>', '2025-11-17 11:48:01'),
(134, 187, 1, 'Bom dia!\r\nOs e-mails constantes no webmail a partir da data/hora mencionada foram encaminhados para o fiqueemdia@crprs.org.br, pois já estavam marcados como \"lidos\", indicando já terem sido baixados pelo Thunderbird. Seguiremos pesquisando sobre o ocorrido.', '2025-11-17 12:23:04'),
(135, 79, 3, 'Bom dia,\r\nVou encerrar esse ticket, mas quando precisar solicitar, pode abrir esse ticket respondendo ou criar um novo ticket.\r\n\r\n', '2025-11-17 12:35:10'),
(136, 186, 3, 'Bom dia!\r\nPor gentileza, nos envie as seguintes informações:\r\n - Modelo do seu celular (ex: Motorola G60, iPhone XR, etc.)\r\n - Versão do sistema operacional (ex: Android 13, iOS 16)\r\n - Versão do aplicativo instalada (verifique se o APP está atualizado na loja de aplicativos)\r\nSe possível, nos envie uma evidência do erro foto ou vídeo curto (podendo ser tirada de outro celular).\r\n\r\nEssas evidências são importantes para que nossa equipe técnica possa analisar o problema com mais precisão.', '2025-11-17 12:53:30'),
(137, 68, 19, 'Bom dia! As ligações não apresentaram mais falhas. Obrigada pelo retorno!\r\n\r\nAtenciosamente,\r\nDocumento sem título\r\n\r\n	Larissa Goya Pierry\r\nPsicóloga Fiscal\r\nCRP 07/25248\r\nlarissa.pierry@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul - Subsede Centro-Oeste\r\nRua Mal. Floriano Peixoto, 1709/401\r\nSanta Maria/RS\r\n(55)  2500.0249\r\nwww.crprs.org.br\r\n\r\n*As informações contidas nesta orientação se aplicam especificamente a \r\neste contexto, não podendo ser utilizadas para outros fins.*\r\n\r\n\r\nEm 11/11/2025 09:21, Suporte CRPRS escreveu:\r\n> Resposta do Ticket\r\n>\r\n>\r\n>   🎫 Nova Resposta no seu Ticket\r\n>\r\n> Olá *larissa.pierry*,\r\n>\r\n> Você recebeu uma nova resposta da nossa equipe de suporte:\r\n>\r\n> *Ticket:* #00068\r\n> *Assunto:* Instabilidade_em_ligações_telefônicas\r\n> *Responsável:* Hugo Miranda\r\n> *Data da Resposta:* 11/11/2025 09:21\r\n>\r\n>\r\n>       📝 Resposta da Equipe:\r\n>\r\n> Bom dia Larissa. Por favor informe como estão as ligações agora.\r\n>\r\n> *💡 Como responder:*\r\n>\r\n> Para continuar a conversa, basta responder (reply) a este e-mail. Sua \r\n> resposta será automaticamente adicionada ao ticket.\r\n>\r\n> Atenciosamente,\r\n>\r\n> ﻿ Documento sem título\r\n>\r\n> 	Equipe de Suporte em Tecnologia da Informação\r\n> Setor de TI\r\n> suporte@crprs.org.br\r\n>\r\n> Conselho Regional de Psicologia do Rio Grande do Sul\r\n> Av. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n> (51) 3334-6799\r\n> www.crprs.org.br\r\n>', '2025-11-17 12:54:01'),
(138, 185, 3, 'Bom dia, \r\nFoi solicitado ao CFP.', '2025-11-17 14:02:41'),
(139, 68, 1, 'Haja vista a resposta da usuaria de que as ligações estão normalizadas, encerro este chamado.', '2025-11-17 14:31:59'),
(140, 75, 1, 'Como não houve mais reposta da solicitante, encerro este chamado.', '2025-11-17 14:33:36'),
(141, 187, 1, 'Márcia, não identifiquei a origem do problema no Thunderbird. Continue observando para vermos se persiste esse tipo de ocorrência. Peço a gentileza de sempre fechar o Thunderbird ao final do expediente, pois a realização do backup (à noite) com ele aberto pode teu impacto sobre a integridade dos arquivos. \r\nPor agora, vou fechar este chamado. Em caso de nova ocorrência, podemos reabri-lo.', '2025-11-17 14:38:35'),
(142, 31, 8, 'Boa tarde,\r\n\r\nSim, continuam entrando ligações. Somente na manhã de hoje foram 8 \r\nligações perdidas.\r\n\r\nAtenciosamente,\r\n\r\nDocumento sem título\r\n\r\n*/As informações contidas nesta orientação se aplicam especificamente a \r\neste contexto, não podendo ser utilizadas para outros fins./*\r\n\r\n\r\n	Geovana da Silva Ferreira\r\nPsicóloga Fiscal\r\nCRP 07/26815\r\ngeovana.ferreira@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br\r\n\r\nEm 14/11/2025 16:37, Suporte CRPRS escreveu:\r\n> Resposta do Ticket\r\n>\r\n>\r\n>   🎫 Nova Resposta no seu Ticket\r\n>\r\n> Olá *geovana.ferreira*,\r\n>\r\n> Você recebeu uma nova resposta da nossa equipe de suporte:\r\n>\r\n> *Ticket:* #00031\r\n> *Assunto:* Re:_Central_telefônica\r\n> *Responsável:* Hugo Miranda\r\n> *Data da Resposta:* 14/11/2025 16:37\r\n>\r\n>\r\n>       📝 Resposta da Equipe:\r\n>\r\n> Oi Geovana. Ainda tem acontecido o recebimento de ligações em teu ramal?\r\n>\r\n> *💡 Como responder:*\r\n>\r\n> Para continuar a conversa, basta responder (reply) a este e-mail. Sua \r\n> resposta será automaticamente adicionada ao ticket.\r\n>\r\n> Atenciosamente,\r\n>\r\n> ﻿ Documento sem título\r\n>\r\n> 	Equipe de Suporte em Tecnologia da Informação\r\n> Setor de TI\r\n> suporte@crprs.org.br\r\n>\r\n> Conselho Regional de Psicologia do Rio Grande do Sul\r\n> Av. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n> (51) 3334-6799\r\n> www.crprs.org.br\r\n>', '2025-11-17 16:05:27'),
(143, 188, 1, 'Mateus, por favor, reencaminhe os e-mails do cadastro@ para o cadastro@ do periodo citado pela Hanna. Tabmém verifica com ela se eles baixaram no Thunderbird dessa vez.', '2025-11-18 15:05:52'),
(144, 31, 1, 'Vamos investigar.', '2025-11-18 16:10:41'),
(145, 31, 1, 'Geovana, identifiquei 4 ligações do Junior de Pelotas, ontem, para teu ramal.  As outras ligações não encontrei por onde entraram. Recoloquei teu número no atendimento e novamente retirei para forçar a central a gravar a saída de teu numero d fila de atendimento. Amanhã vou monitorar aqui pela central se entrarão ligações para ti. Se persistir, vou abrir um chamado junto ao suporte da Central. Sugiro informar às subsedes (se ainda não informaram) que tu e a Antonieta não estão mais fazendo atendimento telefônico.', '2025-11-18 18:02:49'),
