INSERT INTO `tickets` (`id`, `titulo`, `descricao`, `usuario_id`, `email_solicitante`, `agente_id`, `status`, `status_anterior`, `prioridade`, `criado_em`, `atualizado_em`, `categoria_id`, `fechado_por`, `fechado_em`, `tempo_primeiro_atendimento`, `tempo_total_segundos`, `tempo_em_espera_segundos`, `iniciou_espera_em`, `tem_comentario_nao_lido`, `reaberto_contador`, `sla_vencido`) VALUES
(5, 'Migração dos tickets ativos/abertos', 'Mateus, por gentileza, realize a migração manual dos tickets abertos/ativos na versão anterior.\r\nPara cada ticket, lá, abra um ticket aqui. Copie e cole o titulo e a descrição. Na descrição, também mencione, no inicio, a número do ticket na versão anterior.', 1, 'hugo.miranda@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-10-29 20:50:44', '2025-11-28 15:22:17', 74, 1, '2025-10-30 14:58:29', NULL, 0, 0, NULL, 0, 0, 0),
(6, 'Erro no cadastro', 'Ticket anterior: #00031\r\nSolicitante: Raquel Lopes\r\n\r\nBom dia, colegas!\r\n\r\n\r\n    \r\nEncaminho para conhecimento e providências, por gentileza, o erro\r\n      apresentado no BRC do psicólogo LEANDRO MADEIRA OLIVEIRA - 30337.\r\n      \r\n\r\n    \r\n\r\n\r\n    \r\nAtenciosamente,\r\n\r\n    \r\n\r\n\r\n    \r\n\r\n      \r\n      \r\n      \r\n \r\n\r\n            	Raquel Rocha Lopes\r\n\r\n              Assistente Administrativa\r\n\r\n              Setor de Cadastro\r\n\r\n              raquel.lopes@crprs.org.br\r\n\r\n              \r\n\r\n              Conselho Regional de Psicologia do Rio\r\n                Grande do Sul\r\n\r\n              Av. Protásio Alves, 2854/301\r\n\r\n              Porto Alegre/RS\r\n\r\n              (51)\r\n                3334.6799\r\n\r\n              www.crprs.org.br\r\n\r\n    \r\n\r\n    \r\n\r\n\r\n      \r\n\r\n      -------- Mensagem encaminhada --------\r\n      \r\nAssunto:	erro no cadastro\r\nData:	Fri, 26 Sep 2025 19:00:46 +0000 (UTC)\r\nDe:	Leandro Madeira <leandromadeira2004@yahoo.com.br>\r\nPara:	Conselho Regional de Psicologia Do RS - Raquel Rocha\r\n              Lopes <raquel.lopes@crprs.org.br>\r\n\r\n      \r\n\r\n      \r\n\r\n      \r\n\r\n        \r\nInline image\r\n\r\n        \r\n\r\n\r\n          BOA TARDE,\r\n\r\n        \r\n\r\n\r\n        \r\n\r\n        \r\nESTA TENDO UM ERRO NO MEU\r\n          CADASTRO E NÃO CONSIGO AVANÇAR PARA PREENCHER O FORMULÁRIO.\r\n\r\n        \r\n\r\n\r\n        \r\n\r\n        \r\nATENCIOSAMENTE,\r\n\r\n        \r\n\r\n\r\n        \r\n\r\n        \r\nLEANDRO MADEIRA ,CPF\r\n          81279485000\r\n\r\n        \r\nCPR 07/30337\r\n\r\n      \r\n\r\n    \r\n\r\n  \r\n\r\n', 1, 'hugo.miranda@crprs.org.br', 2, 'encerrado', NULL, 'normal', '2025-10-30 11:40:26', '2025-11-28 15:22:17', 10, 2, '2025-10-31 16:48:22', NULL, 0, 0, NULL, 0, 0, 0),
(7, '[MIG] Suporte BRC', 'Ticket anterior: #00029\r\nSolicitante:  Larissa Goya Pierry\r\nData: 29/09/2025\r\n\r\nBom dia!\r\n\r\n    \r\n\r\n        Gostaria de um auxílio, por gentileza, para arquivar um processo\r\n    que está na aba \"OFE\" do BRC, processo de Fiscalização número\r\n    \"2749/2025\", havia tentado apensar ele aos processos 2740/2025 e\r\n    2741/2025, mas, agora não consigo incluir nenhum novo trâmite. Se\r\n    precisar de alguma outra informação, fico à disposição.\r\n\r\n    \r\n\r\n    Atenciosamente,\r\n    \r\n-- \r\n\r\n      \r\n      \r\n      \r\n \r\n\r\n            	Larissa\r\n                Goya Pierry\r\n\r\n              Psicóloga Fiscal\r\n\r\n              CRP 07/25248\r\n\r\n              larissa.pierry@crprs.org.br\r\n\r\n              \r\n\r\n              Conselho Regional de Psicologia do Rio\r\n                Grande do Sul - Subsede Centro-Oeste\r\n\r\n              Rua Mal. Floriano Peixoto, 1709/401\r\n\r\n              Santa Maria/RS\r\n\r\n              (55)\r\n                2500.0249\r\n\r\n              www.crprs.org.br\r\n', 1, 'hugo.miranda@crprs.org.br', 2, 'encerrado', NULL, 'normal', '2025-10-30 11:47:48', '2025-11-28 15:22:17', 10, 2, '2025-10-31 16:49:19', NULL, 0, 0, NULL, 0, 0, 0),
(8, '[MIG00039] Cadastro CRP RS', 'Criado por: Danuza Daudt\r\nPrioridade: normal\r\nData: 01/10/2025, 11:12:29\r\n\r\nColegas, já estou conseguindo imprimir os boletos dentro do \'Protocolo\'. Contudo, não estou conseguindo gerar o boleto da taxa de emissão do certificado, dentro das \'Contas a receber\' no cadastro - PJ MF PSICOLOGIA LTDA. Abaixo a mensagem que aparece:\r\n\r\n\r\n\r\n\r\nDocumento sem título\r\n\r\n	Danuza Daudt\r\nAssistente Administrativa\r\nSetor de Cadastro\r\ndanuza.daudt@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 1, 'hugo.miranda@crprs.org.br', 2, 'encerrado', NULL, 'normal', '2025-10-30 11:55:09', '2025-11-28 15:22:17', 10, 2, '2025-10-31 16:50:12', NULL, 0, 0, NULL, 0, 0, 0),
(9, '[MIG00060] Certidão de Regularidade EM DIA para Inadimplentes', '29/10/2025\r\nDanuza Daudt\r\n\r\nBoa tarde,\r\n    \r\nnecessário verificar a geração normal\r\n      (filtros/critérios/preenchimento) da Certidão de Regularidade PF\r\n      com o \"EM DIA\" para registros que estejam inadimplentes.\r\n\r\n  \r\n', 1, 'hugo.miranda@crprs.org.br', 2, 'aguardando_resposta', NULL, 'baixa', '2025-10-30 11:59:34', '2025-11-28 15:22:17', 10, NULL, NULL, NULL, 0, 0, NULL, 0, 0, 0),
(10, '[MIG00061] Efetivação de transferência e secundária', 'Criado por: Hanna Paula Biskup Fagundes\r\nPrioridade: normal\r\nData: 08/10/2025, 10:51:11\r\n\r\nPrezada(o), bom dia!\r\n\r\n      Por gentileza, solicitamos que a geração de efetivação de\r\n      inscrição secundária e de transferência seja realizada na aba\r\n      “Cadastro”, para que os documentos sejam disponibilizados\r\n      automaticamente no GED, possibilitando o acesso ao documento caso\r\n      seja necessário reenviá-lo via SEI ou por e-mail em outro momento.\r\n\r\n      \r\n\r\n      At.te, ', 1, 'hugo.miranda@crprs.org.br', 2, 'aguardando_resposta', NULL, 'baixa', '2025-10-30 14:01:19', '2025-11-28 15:22:17', 10, NULL, NULL, NULL, 0, 0, NULL, 0, 0, 0),
(12, '[MIG00075] Pedido de PC', 'Criado por: Michele Marques dos Santos\r\nPrioridade: normal\r\nData: 13/10/2025, 11:50:24\r\n\r\nBom dia,\r\n\r\n\r\n    \r\n\r\n\r\n    \r\n\r\n\r\n    \r\nGostaria de solicitar computador com 2 telas para utilização aqui\r\n      na sala. Todavia, necessito permanecer com o notebook, para\r\n      utilização nas reuniões da Diretoria e COE.\r\n\r\n\r\n    \r\nGrata.', 1, 'hugo.miranda@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-10-30 14:10:14', '2025-11-28 15:22:17', 5, 3, '2025-11-05 12:50:04', NULL, 0, 0, NULL, 0, 0, 0),
(13, '[MIG00087] Protocolo de Representação', 'Criado por: Flavia Cardozo de Mattos\r\nPrioridade: normal\r\nData: 17/10/2025, 16:02:50\r\n\r\nBoa tarde, colegas. \r\n\r\nEstamos adotando alguns modelos de documentos do\r\n      Conselho Federal de Psicologia na Comissão de Ética. Um dos\r\n      modelos que queremos implantar é o Protocolo de Representação,\r\n      tornando-o obrigatório para aquelas pessoas que marcam, no nosso\r\n      formulário, o campo \"desejo representar\". \r\n\r\nEnvio o modelo anexo, no pedido de que me ajudem\r\n      a pensar na melhor forma de disponibilizá-lo. Podemos\r\n      transformá-lo em campos do nosso próprio Google Forms ou informar,\r\n      de forma bastante visível, que a denúncia só será aceita mediante\r\n      apresentação deste documento, integralmente preenchido. É\r\n      importante frisar a obrigatoriedade deste item. \r\n    \r\nFico à disposição para conversarmos, buscando o\r\n      melhor ajuste, e agradeço desde já. \r\n\r\nAtenciosamente. ', 1, 'hugo.miranda@crprs.org.br', 1, 'aguardando', NULL, 'baixa', '2025-10-30 14:13:01', '2025-11-28 18:43:52', 82, NULL, NULL, NULL, 0, 0, NULL, 0, 0, 0),
(14, '[MIG00068] Problema no protocolo do BRC', 'Solicitado por José Junior\r\n\r\nBoa tarde,\r\n     \r\n      Estou enfrentando um problema com este protocolo. Não estou\r\n      conseguindo alterar as atualizações — aparece a mensagem conforme\r\n      imagem em anexo.\r\n      \r\n      Agradeço desde já pelo apoio.\r\n      \r\n      Atenciosamente,', 1, 'hugo.miranda@crprs.org.br', 2, 'encerrado', NULL, 'normal', '2025-10-30 14:15:15', '2025-11-28 15:22:17', 10, 2, '2025-11-04 16:48:25', NULL, 0, 0, NULL, 0, 0, 0),
(15, '[MIG00092] Liberação COE', 'Criado por: Antonieta Martins Lopes Bridi\r\nPrioridade: normal\r\nData: 21/10/2025, 13:50:22\r\n\r\nAo suporte de T.I.,\r\n\r\nSolicitamos, por gentileza, liberação para que as fiscais\r\n      Antonieta e Geovana possam excluir documentos no GED de processos\r\n      BRC da COE.\r\n    \r\nA coordenadora técnico-política, Flávia, em cópia deste e-mail,\r\n      está ciente e autoriza o referido pedido.\r\n\r\nAtenciosamente,', 1, 'hugo.miranda@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-10-30 14:17:44', '2025-11-28 15:22:17', 10, 2, '2025-10-31 16:44:59', NULL, 0, 0, NULL, 0, 0, 0),
(16, '[MIG00096] NOTEBOOK COORDENADOR COMUNICAÇÃO', 'Criado por: Guilherme Bernst Roesler\r\nPrioridade: normal\r\nData: 22/10/2025, 13:22:54\r\n\r\nBoa tarde!\r\n  \r\nSolicito um notebook para demandas do trabalho.\r\n\r\nAtenciosamente', 1, 'hugo.miranda@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-10-30 14:20:31', '2025-11-28 15:22:17', 5, 3, '2025-11-07 15:34:03', NULL, 0, 0, NULL, 0, 0, 0),
(17, '[MIG00099] Solicitação de Telefone para a Subsede de Pelotas', 'Criado por: José Antônio Lages Junior\r\nPrioridade: normal\r\nData: 22/10/2025, 15:25:24\r\n\r\nPrezados,\r\n\r\n    Em atendimento à solicitação do Coordenador Administrativo, venho\r\n    solicitar a disponibilização de um telefone fixo com sinal de Wi-Fi\r\n    para a Subsede.\r\n\r\n    Ressalto que, desde a mudança de sala realizada pelo então\r\n    Coordenador Administrativo, há cerca de dois meses, estou utilizando\r\n    o celular da Subsede para suprir essa necessidade.\r\n\r\n    Agradeço desde já pela atenção e fico à disposição para quaisquer\r\n    esclarecimentos.\r\n\r\n    Atenciosamente,', 1, 'hugo.miranda@crprs.org.br', 1, 'aguardando_resposta', NULL, 'baixa', '2025-10-30 14:22:16', '2025-11-28 15:22:17', 3, NULL, NULL, NULL, 0, 0, NULL, 0, 0, 0),
(18, '[MIG00100] CONCLUIR PROTOCOLOS ANTIGOS - SUBSEDE CENTRO-OESTE', 'Solicitante: Subsede Centro-Oeste (santamaria@crprs.org.br)\r\nPrezados, \r\n\r\n      Solicito que sejam concluídos, em lote, os protocolos abertos no\r\n      departamento de origem Subsede CENTRO-OESTE em nome de Flaviane,\r\n      referentes ao período anterior a 2022.', 1, 'hugo.miranda@crprs.org.br', 2, 'aguardando_resposta', NULL, 'normal', '2025-10-30 14:24:26', '2025-11-28 15:22:17', 10, NULL, NULL, NULL, 0, 0, NULL, 0, 0, 0),
(19, '[MIG00102] Acesso SISCONT. Permissões Aline', 'Criado por: Marcelo Borges Teixeira\r\nPrioridade: normal\r\nData: 22/10/2025, 16:51:54\r\nRueda, \r\n\r\n      Peço, por gentileza, verificar a permissão de acesso da Aline para\r\n      que ela possa gerar e administrar os acessos do pessoal com acesso\r\n      ao SISCONT.\r\n\r\n      Atenciosamente,', 1, 'hugo.miranda@crprs.org.br', 1, 'encerrado', NULL, 'normal', '2025-10-30 14:27:48', '2025-11-28 15:22:17', 69, 1, '2025-10-30 17:28:06', NULL, 0, 0, NULL, 0, 0, 0),
(20, '[MIG00107] ajuste formulário de inscrição', 'Prezada(o), bom dia!\r\n \r\n Precisamos de auxílio para o ajuste do formulário de inscrição\r\n      de pessoa física (PF).\r\n\r\n  \r\nInclusão do campo Prouni e Cadúnico \r\n\r\n      \r\n Você utilizou algum benefício do governo durante a sua\r\n        graduação? Não  \r\n        Sim   \r\n\r\n      \r\nSe sim, qual? abrir para selecionar - Prouni ou Cadúnico (E\r\n        essa informação deve ficar\r\n          visível posteriormente na aba de cadastro quando o registro do\r\n        profissional for aberto, tem como?)\r\n   \r\nTambém é necessário criar o anexo beneficio gov para quem\r\n      informou que utilizou o beneficio durante a graduação. Podemos\r\n      tornar esse anexo obrigatório quando o profissional marcar essa\r\n      opção?', 1, 'hugo.miranda@crprs.org.br', 2, 'encerrado', NULL, 'urgente', '2025-10-30 14:31:03', '2025-11-28 15:22:17', 10, 2, '2025-11-07 19:12:27', NULL, 0, 0, NULL, 0, 0, 0),
(21, '[MIG00109] DECLARAÇÃO DE REGULARIDADE', 'Boa tarde,\r\n\r\n\r\nFavor verificar e dar retorno à psicóloga.\r\n\r\n\r\nObs. Certidão já foi enviada pra ela.\r\n\r\n\r\nObrigado.\r\n\r\n\r\n \r\n\r\n\r\n\r\n\r\n-------- Mensagem original --------\r\n\r\n\r\nAssunto::	DECLARAÇÃO DE REGULARIDADE\r\nData:	27/10/2025 18:34\r\nDe:	daia duarte <daiaduarte@gmail.com>\r\nPara::	crprs@crprs.org.br\r\n\r\n\r\n\r\n\r\n\r\n\r\nOlá \r\n\r\nNovamente necessito da declaração de regularidade e, novamente o site gera uma mensagem de \"usuário bloqueado\", sendo que estou ativa e com anuidade em dia.\r\n\r\nVeja a mensagem em anexo.\r\n\r\n \r\n\r\n*Por favor, preciso deste documento com urgência.', 1, 'hugo.miranda@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-10-30 14:32:34', '2025-11-28 15:22:17', 10, 3, '2025-10-30 14:38:10', NULL, 0, 0, NULL, 0, 0, 0),
(22, '[MIG00110] Implanta.net. Acesso Keli. Senha', 'Criado por: Marcelo Borges Teixeira\r\nPrioridade: normal\r\nData: 29/10/2025, 08:09:12\r\n\r\nHugo, \r\n\r\n      Conforme conversamos ontem, solicito que verifique a geração de\r\n      senha da Keli.    \r\n\r\n      Ao consultar o sistema, constatei que já existe usuário.\r\n\r\n      Atenciosamente,', 1, 'hugo.miranda@crprs.org.br', 1, 'encerrado', NULL, 'normal', '2025-10-30 14:40:18', '2025-11-28 15:22:17', 69, 1, '2025-10-30 17:33:46', NULL, 0, 0, NULL, 0, 0, 0),
(23, '[MIG00111] protocolos duplicados', 'Criado por: Cadastro\r\nPrioridade: normal\r\nData: 29/10/2025, 15:55:11\r\n\r\nPrezada(o), boa tarde!\r\n    \r\nEstamos novamente com protocolos\r\n      de inscrição de Pessoa Física (PF) duplicados.\r\n    \r\nPoderiam, por gentileza,\r\n      verificar se o sistema está permitindo a abertura de mais de um\r\n      protocolo para o mesmo serviço?\r\n\r\n\r\n      At.te, ', 1, 'hugo.miranda@crprs.org.br', 2, 'encerrado', NULL, 'normal', '2025-10-30 14:41:54', '2025-11-28 15:22:17', 10, 2, '2025-10-31 16:57:23', NULL, 0, 0, NULL, 0, 0, 0),
(26, 'Permissões_Módulo_Siscont_x_Logística', 'Prezados,\r\n\r\nOntem a tarde a Contadora Aline encerrou a revisão das permissões \r\nnecessárias para o GRUPO FINANCEIRO.\r\n\r\nContatei que no grupo LOGÍSTICA conta acesso ao módulo SISCONT. Salvo \r\nengano, entendemos que a Logística não deva ter acesso ao módulo \r\nSISCONT. Caso seja necessário para futura funcionalidade do módulo \r\nSISPAD junto ao setor de Logística, devemos revisar junto à \r\nContabilidade quais permissões devam ser concedidas.\r\n\r\nNeste sentido, considerando que o grupo FINANCEIRO já está configurado e \r\nrevisado pelo setor de contabilidade, questiono como podemos importar as \r\nconfigurações do módulo SISCONT para o grupo criado \r\nFINANCEIRO+LOGISTICA, pensando no usuário da Patrícia Cristina?\r\n\r\nInicialmente tentei replicar as permissões do grupo revisado pela \r\ncontabilidade, porém verifiquei que seria manualmente um a um.\r\n\r\nAtenciosamente,\r\n\r\nDocumento sem título\r\n\r\n	Marcelo Borges Teixeira\r\nCoordenador Financeiro\r\nmarcelo.teixeira@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 5, 'marcelo.teixeira@crprs.org.br', 1, 'encerrado', NULL, 'normal', '2025-10-30 16:52:55', '2025-11-28 15:22:17', 69, 1, '2025-10-30 17:54:22', NULL, 0, 0, NULL, 0, 0, 0),
(27, 'Troca_de_estações_de_trabalho_-_Setor_de_cadastro', 'Prezado,\r\n\r\nConforme falamos, gostaria de realizar a troca da disposição das mesas \r\ndo Setor de Cadastro no dia 31/10, às 14.\r\n\r\nObrigado.\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	André Sommer Bertão\r\nCoordenador Administrativo\r\nandre.bertao@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 6, 'andre.bertao@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-10-30 16:53:00', '2025-11-28 15:22:17', 81, 3, '2025-11-03 12:09:01', NULL, 0, 0, NULL, 0, 0, 0),
(28, 'Assinatura SEI - Unidade Cadastro', 'Bom dia,\r\n\r\nFavor incluir o cargo de Coordenador Administrativo nos documentos a \r\nserem assinados dentro da unidade 07/Cadastro.\r\n\r\nObrigado.\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	André Sommer Bertão\r\nCoordenador Administrativo\r\nandre.bertao@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 6, 'andre.bertao@crprs.org.br', 1, 'encerrado', NULL, 'normal', '2025-10-30 16:53:05', '2025-11-28 15:22:17', 11, 1, '2025-11-06 17:43:41', NULL, 0, 0, NULL, 0, 0, 0),
(30, 'MUDANÇA_LOGIN_-_BANCO_DE_PREÇOS', 'Boa tarde!\r\n\r\nPrecisava fazer uma mudança no login do site Banco de Preços. Ele \r\ncontinua no e-mail do antigo coordenador de comunicação.\r\n\r\nDesde já agradeço.\r\n\r\n\r\nAtt,\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	Guilherme Bernst Roesler\r\nCoordenador de Comunicação\r\nguilherme.roesler@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 7, 'guilherme.roesler@crprs.org.br', 1, 'encerrado', NULL, 'normal', '2025-10-30 17:18:01', '2025-11-28 15:22:17', 83, 1, '2025-11-03 19:14:04', NULL, 0, 0, NULL, 0, 0, 0),
(31, 'Re:_Central_telefônica', 'Boa tarde,\r\n\r\nInformo que meu ramal (1214) ainda está recebendo ligações a partir do \r\nrodízio da central telefônica.\r\n\r\nDocumento sem título\r\n\r\n*/As informações contidas nesta orientação se aplicam especificamente a \r\neste contexto, não podendo ser utilizadas para outros fins./*\r\n\r\n\r\n	Geovana da Silva Ferreira\r\nPsicóloga Fiscal\r\nCRP 07/26815\r\ngeovana.ferreira@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br\r\n\r\nEm 06/10/2025 11:42, Conselho Regional de Psicologia do RS - Flavia \r\nCardozo de Mattos escreveu:\r\n>\r\n> Bom dia, colegas do TI.\r\n>\r\n> Por gentileza, preciso que as Fiscais Antonieta e Geovana sejam \r\n> retiradas do rodízio da central telefônica, pois estão atuando \r\n> exclusivamente no assessoramento à Comissão de Ética.\r\n>\r\n> Muito obrigada.\r\n>\r\n> Atenciosamente.\r\n>\r\n>\r\n> 	Flávia Cardozo de Mattos\r\n> Coordenadora Técnico-Política\r\n> CRP 07/15863\r\n> flavia.mattos@crprs.org.br\r\n>\r\n> Conselho Regional de Psicologia do Rio Grande do Sul\r\n> Av. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n> (51) 3334.6799\r\n> www.crprs.org.br\r\n>', 8, 'geovana.ferreira@crprs.org.br', 1, 'encerrado', NULL, 'normal', '2025-10-30 19:00:04', '2025-12-02 12:51:11', 77, 1, '2025-12-02 12:51:11', NULL, 0, 0, NULL, 0, 0, 0),
(32, 'Alterações_no_BRC', 'Boa tarde, \r\n\r\nConforme deliberado na última reunião Plenária, a presidenta da CARPE\r\nserá a Conselheira Esther Abgail Helena. \r\n\r\nPeço, por gentileza, que a seja liberado o acesso ao BRC para\r\nConselheira nas questões relacionadas aos trâmites da Comissão (os\r\nmesmos acessos que o ex Conselheiro Diego tinha na CARPE). \r\n\r\nObrigado. \r\n\r\nAtenciosamente, \r\n\r\nAndré Sommer Bertão\r\nCoordenador Administrativo\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\n\r\n-- \r\n\r\n Diretoria CRPRS\r\ndirecao@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 9, 'direcao@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-10-30 19:08:01', '2025-11-28 15:22:17', 10, 3, '2025-10-31 12:23:18', NULL, 0, 0, NULL, 0, 0, 0),
(33, 'Re: Liberação COE', 'Boa tarde!\r\n\r\nReitero o pedido da Antonieta, e solicito maior brevidade possível para \r\na liberação.\r\n\r\nAtenciosamente,\r\n\r\nDocumento sem título\r\n\r\n*/As informações contidas nesta orientação se aplicam especificamente a \r\neste contexto, não podendo ser utilizadas para outros fins./*\r\n\r\n\r\n	Geovana da Silva Ferreira\r\nPsicóloga Fiscal\r\nCRP 07/26815\r\ngeovana.ferreira@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br\r\n\r\nEm 21/10/2025 13:49, Conselho Regional de Psicologia do RS - Antonieta \r\nMartins Lopes Bridi escreveu:\r\n>\r\n> Ao suporte de T.I.,\r\n>\r\n> Solicitamos, por gentileza, liberação para que as fiscais Antonieta e \r\n> Geovana possam excluir documentos no GED de processos BRC da COE.\r\n>\r\n> A coordenadora técnico-política, Flávia, em cópia deste e-mail, está \r\n> ciente e autoriza o referido pedido.\r\n>\r\n> Atenciosamente,\r\n>\r\n> -- \r\n> Documento sem título\r\n>\r\n> 	Antonieta Martins Lopes Bridi\r\n> Psicóloga Fiscal\r\n> CRP 07/23600\r\n> antonieta.bridi@crprs.org.br\r\n>\r\n> Conselho Regional de Psicologia do Rio Grande do Sul\r\n> Av. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n> (51) 3334.6799\r\n> www.crprs.org.br\r\n>\r\n> *As informações contidas nesta orientação se aplicam especificamente a \r\n> este contexto, não podendo ser utilizadas para outros fins.*\r\n>', 8, 'geovana.ferreira@crprs.org.br', 1, 'encerrado', NULL, 'normal', '2025-10-30 19:44:01', '2025-11-28 15:22:17', 10, 1, '2025-10-31 14:35:27', NULL, 0, 0, NULL, 0, 0, 0),
(34, '[MIGSW01190] Atualização no site e nos formulários PJ', 'hanna.fagundes@crprs.org.br\r\nJul 18, 2025 5:01 PM\r\n\r\nBoa tarde,\r\n\r\nPrecisamos alterar algumas informações do site e dos formulários.\r\n\r\n*_FORMULÁRIOS_*\r\n\r\n  * Inscrição PJ é necessário colocar a opção de escolha para registro\r\n    ou cadastro, abaixo coloquei uma ideia para incluir no formulário.\r\n\r\n\r\n      *Informações sobre a atividade de Psicologia na empresa*\r\n\r\nA Psicologia está registrada como:\r\n☐ *Atividade principal*\r\n☐ *Atividade secundária*\r\n\r\n*Se você marcou \"Atividade secundária\", deseja solicitar:*\r\n☐ *Registro no Conselho* – verificar Capítulo I da Resolução CFP nº 16/2019\r\n☐ *Cadastro no Conselho* – verificar Capítulo II da Resolução CFP nº 16/2019\r\n\r\n\r\n  * Formulário renovação\r\n\r\nEsse texto deve estar de acordo com a resolução 16/2019\r\n\r\nArt. 5ºDeferido o pedido, o Conselho Regional de Psicologia emitirá \r\nCertificado de Registro com validade de três anos em toda a área de sua \r\njurisdição, que deverá ser afixado em local visível ao público, durante \r\ntodo o período de atividades.\r\n\r\n§ 1º A renovação do certificado deverá ser requerida pela empresa antes \r\nda data de vencimento do documento, com antecedência mínima de sessenta \r\ndias, apresentando os seguintes documentos:\r\n\r\nI - termo de Responsabilidade Técnica;\r\n\r\nII - carta da empresa assinada pelas(os) sócias(os) ou responsáveis \r\nlegais, conforme contrato social da empresa, solicitando a renovação do \r\ncertificado de licença para prestar atividades de Psicologia, podendo \r\nser realizada de modo eletrônico.\r\n\r\nIII - última alteração contratual;\r\n\r\nIV - certificado de Registro em outro conselho de classe, se possuir.\r\n\r\n\r\n*_ALTERAÇÕES SITE\r\n_*\r\n\r\nIncluir o item - Cópia simples atualizada do Certificado de Registro da \r\nPessoa Jurídica em outro Conselho de fiscalização Profissional, se houver;\r\n\r\nInformação sobre prazo do site: de acordo com a resolução 16/2019 - A \r\nrenovação do certificado deverá ser requerida pela empresa antes da data \r\nde vencimento do documento, *com antecedência mínima de sessenta dias*,\r\n\r\n\r\nAt.te,\r\n', 3, 'mateus.pereira@crprs.org.br', 1, 'aguardando_terceiros', NULL, 'baixa', '2025-10-31 12:39:41', '2025-11-28 15:22:17', 56, NULL, NULL, NULL, 0, 0, NULL, 0, 0, 0),
(36, '[MIGSW01288 ] Inclusão/Sugestão BRC', 'hanna.fagundes@crprs.org.br\r\nAug 20, 2025 9:49 AM\r\nBom dia,\r\n\r\nPor gentileza, podemos solicitar ao BRC que seja incluído a opção de \r\nenviar boleto por e-mail na aba protocolo?\r\n\r\n\r\nAt.te,', 3, 'mateus.pereira@crprs.org.br', 2, 'aguardando_resposta', NULL, 'normal', '2025-10-31 12:48:59', '2025-11-28 15:22:17', 10, NULL, NULL, NULL, 0, 0, NULL, 0, 0, 0),
(37, '[MIGSW01320] Inclusão de acompanhamento externo do protocolo', 'hanna.fagundes@crprs.org.br\r\nSep 01, 2025 12:08 PM\r\nBom dia,\r\n\r\nConforme conversamos na reunião de sexta-feira, precisamos incluir no \r\nprotocolo BRC a possibilidade de acompanhamento do processo pelo público \r\nexterno ou melhorias relacionadas ao peticionamento online.\r\n\r\n\r\nAt.te,', 3, 'mateus.pereira@crprs.org.br', 2, 'encerrado', NULL, 'normal', '2025-10-31 12:50:50', '2025-11-28 15:22:17', 10, 2, '2025-11-04 16:52:47', NULL, 0, 0, NULL, 0, 0, 0),
(39, '[MIGSW01322 ] Taxa de inscrição PF \"automática\"', 'hanna.fagundes@crprs.org.br\r\nSep 01, 2025 4:14 PM\r\nBoa tarde,\r\n\r\nPodemos deixar agendada, pelo protocolo, a geração automática da taxa de \r\ninscrição a partir do dia 05/09, às 9h\r\n\r\nAt.te,', 3, 'mateus.pereira@crprs.org.br', 2, 'encerrado', NULL, 'baixa', '2025-10-31 12:54:22', '2025-12-01 14:00:55', 10, 2, '2025-12-01 14:00:55', NULL, 0, 0, NULL, 0, 0, 0),
(40, '[MIGSW01331 ] Verificação Campos Obrigatórios CADASTRO', 'marcia.castro@crprs.org.br\r\nSep 05, 2025 11:42 AM\r\nPrezados,\r\n\r\no campo CEP não está marcado em vermelho como obrigatório nas telas do \r\ncadastro, tanto no End. Residencial quanto no End. Profissional.\r\n\r\nE necessário colocar o campo \"email\" como de preenchimento obrigatório \r\nao selecionar como ativo qual o Endereço para Correspondência. \r\nPrecisamos necessariamente de email cadastrado para envio das \r\ncorrespondências da cobrança.\r\n\r\nAguardamos.\r\n\r\nAt.te,', 3, 'mateus.pereira@crprs.org.br', 2, 'aguardando_terceiros', NULL, 'normal', '2025-10-31 12:56:23', '2025-11-28 15:22:17', 10, NULL, NULL, NULL, 0, 0, NULL, 0, 0, 0),
(41, '[MIGSW01086 ] Revisar Nome Social em Todos Documentos Emitidos pelo BRC', 'Rafael Rueda\r\nJun 10, 2025 4:57 PM\r\nRevisar os documentos emitidos pelos profissionais se estão com tratamento de Nome Social.\r\n\r\nO tratamento foi colocado, como exemplo, no Template Ofício/Efetivação de Transferência Sem CIP (Código Cadastro33).', 3, 'mateus.pereira@crprs.org.br', 2, 'aguardando_terceiros', NULL, 'baixa', '2025-10-31 12:58:00', '2025-11-28 15:22:17', 10, NULL, NULL, NULL, 0, 0, NULL, 0, 0, 0),
(42, '[MIG01327 ] Organização BRC - registros da Área Técnica', 'flavia.mattos@crprs.org.br\r\nSep 04, 2025 1:57 PM\r\nBoa tarde.\r\n\r\nConforme combinado em Reunião Técnica na manhã de hoje, na presença do \r\nCoordenador de TI, solicito que sejam procedidos os seguintes ajustes no \r\nBRC:\r\n\r\n1) No campo TIPO DE TAREFA, manter *ativos *somente os campos abaixo \r\nindicados.\r\n\r\n  * Fiscalização de Rotina\r\n  * Fiscalização de Averiguação\r\n  * Fiscalização Estratégica\r\n  * Orientação por Convocação\r\n  * Orientação por Ofício\r\n  * Orientação por E-mail\r\n  * Orientação por Telefone\r\n  * Orientação por Vídeochamada\r\n  * Orientação Presencial\r\n  * Orientação Coletiva\r\n\r\n2) Configurar os campos de modo que TEMA/ASSUNTO, TIPO DE DEMANDA E TIPO \r\nDE TAREFA exijam preenchimento obrigatório.\r\n\r\n3) No campo TEMA/ASSUNTO, tornar *_inativos_ *os campos abaixo indicados:\r\n\r\n  * Autorização/atendimento psicológico durante a pandemia de COVID-19\r\n  * Cadastro\r\n  * Demandas sindicais e do trabalho\r\n  * E-psi\r\n  * Estágio curricular\r\n  * Pronome neutro\r\n  * Registro de especialista\r\n  * Vacina COVID\r\n\r\n4) No campo TIPO LOCAL DE ATUAÇÃO, substituir todos os itens \r\n(tornando-os inativos) pela lista de especialidades reconhecidas pelo \r\nCFP \r\n, \r\nindicadas abaixo. Se for possível mudar o nome do campo, alterar para \r\nCAMPO DE ATUAÇÃO.\r\n\r\n  * I - Psicologia Escolar e Educacional;\r\n  * II - Psicologia Organizacional e do Trabalho;\r\n  * III - Psicologia de Tráfego;\r\n  * IV - Psicologia Jurídica;\r\n  * V - Psicologia do Esporte;\r\n  * VI - Psicologia Clínica\r\n  * VII - Psicologia Hospitalar;\r\n  * VIII - Psicopedagogia;\r\n  * IX - Psicomotricidade;\r\n  * X - Psicologia Social;\r\n  * XI - Neuropsicologia;\r\n  * XII - Psicologia em Saúde; e\r\n  * XIII - Avaliação Psicológica.\r\n\r\n4) Configurar todos os campos mencionados acima de modo que apenas a \r\nCoordenação Técnico-Política possa fazer inclusão ou exclusão de novos \r\nitens.\r\n\r\nAgradeço desde já e permaneço à disposição.\r\n\r\nAtenciosamente.', 3, 'mateus.pereira@crprs.org.br', 2, 'aguardando_terceiros', NULL, 'baixa', '2025-10-31 12:59:34', '2025-11-28 15:22:17', 10, NULL, NULL, NULL, 0, 0, NULL, 0, 0, 0),
(43, 'Redirecionamento e-mail', 'Bom dia,\r\n\r\nSolicito cópia dos e-mails enviados para o endereço *caxias**@* para a \r\nminha caixa de entrada, *no período de 31/10, a partir das **17h*, \r\ndurante as férias do colega Jean\r\n\r\n\r\nAt.te,\r\n\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	Hanna Paula Biskup Fagundes\r\nSupervisora do Setor de Cadastro\r\nhanna.fagundes@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 11, 'hanna.fagundes@crprs.org.br', 1, 'encerrado', NULL, 'normal', '2025-10-31 15:02:02', '2025-11-28 15:22:17', 31, 1, '2025-11-10 11:28:40', NULL, 0, 0, NULL, 0, 0, 0),
(44, 'Férias_Luis._03/11_a_21/11._Direcionamento_do_e-mail', 'Prezados,\r\n\r\nFavor incluir direcionamento do email do @Luis para @Vinicius.\r\n\r\nAtenciosamente,\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	Marcelo Borges Teixeira\r\nCoordenador Financeiro\r\nmarcelo.teixeira@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 5, 'marcelo.teixeira@crprs.org.br', 1, 'encerrado', NULL, 'normal', '2025-10-31 19:24:01', '2025-11-28 15:22:17', 31, 1, '2025-11-24 12:53:34', NULL, 0, 0, NULL, 0, 0, 0),
(45, 'declaração_de_atividade_e_cancelamento', 'Prezada(o), boa tarde!\r\nPor gentileza, solicitamos uma declaração que discrimine os períodos em \r\nque o profissional esteve ativo e cancelado. A declaração disponível no \r\nsistema atualmente não apresenta essa separação dos períodos.\r\n\r\n\r\n\r\n\r\nAt.te,\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	Hanna Paula Biskup Fagundes\r\nSupervisora do Setor de Cadastro\r\nhanna.fagundes@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br\n\n📎 1 anexo(s) do email foram salvos.', 11, 'hanna.fagundes@crprs.org.br', 2, 'aguardando_terceiros', NULL, 'normal', '2025-11-03 16:06:01', '2025-11-28 15:22:17', 10, NULL, NULL, NULL, 0, 0, NULL, 0, 0, 0),
(46, 'isenção_permanente_2026', 'Prezada(o), boa tarde!\r\n\r\nSolicito, por gentileza, a verificação quanto à programação do sistema \r\npara a aplicação automática da isenção permanente aos profissionais que \r\ncompletarão 65 anos em 2026.\r\n\r\n\r\nAt.te,\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	Hanna Paula Biskup Fagundes\r\nSupervisora do Setor de Cadastro\r\nhanna.fagundes@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 11, 'hanna.fagundes@crprs.org.br', 2, 'encerrado', NULL, 'normal', '2025-11-03 17:56:01', '2025-11-28 15:22:17', 10, 2, '2025-11-04 12:34:56', NULL, 0, 0, NULL, 0, 0, 0),
(47, 'Notebook_para_Curso_de_Formação', 'Bom dia,\r\n\r\nSolicito, por gentileza, o empréstimo de um notebook do Conselho para \r\nutilização em curso que participarei de 10 a 12 de novembro.\r\n\r\nComo viajarei no domingo, dia 9 de novembro, preciso que esteja liberado \r\naté sexta-feira, dia 7/11.\r\n\r\n\r\nAtenciosamente,\r\n\r\nDocumento sem título\r\n\r\n	Cícero Bortolini\r\nAssistente Administrativo\r\nSetor de Licitações e Contratos\r\ncicero.bortolini@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 12, 'cicero.bortolini@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-11-04 12:00:04', '2025-11-28 15:22:17', 88, 3, '2025-11-07 15:22:36', NULL, 0, 0, NULL, 0, 0, 0),
(48, 'Ajuste dos e-mails enviados para a Comunicação', 'Mateus, o pessoal da Comunicação está recebendo e-mails duplicados. A Nádia está recebendo triplicados. Segue abaixo  informações da Nádia sobre quem deve receber quais e-mails, na Comunicação:\r\n\r\ncomunicacao@ - direcionar a guilherme.roesler@ e nadia.miola@\r\ncomunicacao2@ - direcionar para a nadia.miola@\r\ncomunicacao3@ - é recebido no Thunderbird do Giovani - Colocar cópia para guilherme.roesler@\r\ncomunicacao4@ - É recebido no Thunderbird da Estagiária RP - Colocar cópia para nadia.miola@\r\nimprensa@ - direcionar a aline.victorino@, guilherme.roesler@ e imprensa2@\r\nimprensa2@ - Recebido no Thunder do João Felipe - Colocar cópia para aline.victorino@\r\ntomas.rodrigues@ - direcionar para guilherme.roesler@\r\nAcredito que o eventos@ (que era utilizado pela Adriana) também esteja direcionado para mim. Não usamos, pode extinguir ou tudo bem manter direcionado pra mim (nadia.miola@). \r\nAs caixas dos e-mails encontrogaucho@ e cnp@ são de uso sazonais, mas podem seguir comigo (nadia.miola@).', 1, 'hugo.miranda@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-11-04 13:07:59', '2025-11-28 15:22:17', 31, 3, '2025-11-04 13:28:25', NULL, 0, 0, NULL, 0, 0, 0),
(49, 'Monitor com Problemas', 'Bom Dia,\r\n\r\nMeu monitor esta apresentando problemas desde o dia de ontem, a tela \r\ncomeça a ficar pixelada e fica apagando e voltando.\r\n\r\nsegue em anexo vídeo que eu consegui gravar referente aos problemas.\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	Luis Paulo Francisco da Silva\r\nEstagiário - Patrimônio e Compras\r\nluis.silva@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 13, 'luis.silva@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-11-04 13:22:01', '2025-11-28 15:22:17', 4, 3, '2025-11-11 13:43:52', NULL, 0, 0, NULL, 0, 0, 0),
(50, 'Realocação_de_Pessoal._COE,_CAD_e_COB', 'Prezados,\r\n\r\nConforme deliberação da Coordenação Geral, e anuência das Coordenações \r\ndas Áreas envolvidas, solicito que seja providenciado, a partir das 13h \r\nde hoje, as seguintes realocações das estações de trabalho:\r\n\r\n  * Célia alocada no Setor de Cadastro\r\n  * Renata alocada na COE\r\n  * Carlos Eduardo alocado no Setor de Cobrança\r\n\r\nPara a instalação dos equipamentos, deve ser priorizada a ordem posta acima.\r\n\r\nPara o perfil da Renata, deverá ser atrelada as configurações \r\nnecessárias para o perfil da Ouvidoria.\r\n\r\nAtenciosamente,\r\n\r\nDocumento sem título\r\n\r\n	Marcelo Borges Teixeira\r\nCoordenador Financeiro\r\nmarcelo.teixeira@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 5, 'marcelo.teixeira@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-11-04 13:32:01', '2025-11-28 15:22:17', 81, 1, '2025-11-04 20:43:10', NULL, 0, 0, NULL, 0, 0, 0),
(51, 'Remover_a_opção_de_subsede', 'Prezada(o), bom dia!\r\n\r\nHá possibilidade de remover a opção de criação de protocolo com o \r\ndepartamento de origem “Subsedes”?\r\n\r\nAtualmente, quando buscamos um protocolo, se ele não estiver vinculado \r\nao nosso departamento (Cadastro), não conseguimos visualizá-lo na aba de \r\nconcluídos, apenas em “somente leitura”.\r\n\r\nSegue abaixo um exemplo para ilustrar a situação.\r\n\r\n\r\n\r\nAt.te,\r\nDocumento sem título\r\n\r\n	Hanna Paula Biskup Fagundes\r\nSupervisora do Setor de Cadastro\r\nhanna.fagundes@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br\n\n📎 2 anexo(s) do email foram salvos.', 11, 'hanna.fagundes@crprs.org.br', 2, 'encerrado', NULL, 'normal', '2025-11-04 13:52:01', '2025-11-28 15:22:17', 10, 2, '2025-11-04 14:19:13', NULL, 0, 0, NULL, 0, 0, 0),
(52, 'CARPE', 'Boa tarde colegas.\r\n\r\nAo setor de TI, solicito inclusão das Fiscais Kwala e Letícia na CARPE \r\n(SEi e BRC), conforme portaria anexa, bem como das Conselheiras Esther \r\nAbigail Helena Maciel Nunes e Vanessa Arlete Marques Cazelato.\r\n\r\nÀ Assistente Administrativa Cristina, solicito que distribua igualmente \r\nos processos da CARPE entre os Fiscais portariados.\r\n\r\nAos Fiscais, seguimos fazendo as combinações necessárias em reunião.\r\n\r\nAgradeço desde já.\r\n\r\nAtenciosamente.\r\n\r\n\r\n	Flávia Cardozo de Mattos\r\nCoordenadora Técnico-Política\r\nCRP 07/15863\r\nflavia.mattos@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br\n\n📎 1 anexo(s) do email foram salvos.', 14, 'flavia.mattos@crprs.org.br', 1, 'encerrado', NULL, 'normal', '2025-11-04 17:46:01', '2025-11-28 15:22:17', 72, 1, '2025-11-07 14:30:45', NULL, 0, 0, NULL, 0, 0, 0),
(53, 'ACESSO AO CAV - CELIA VITT', 'Boa tarde,\r\n\r\nsolicito, por gentileza, acesso ao CAV para a funcionária Célia Vitt.\r\n\r\n\r\n\r\nAt.te,\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	Hanna Paula Biskup Fagundes\r\nSetor de Cadastro\r\ncadastro2@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n(51)  3334.6799\r\nwww.crprs.org.br', 15, 'cadastro2@crprs.org.br', 1, 'encerrado', NULL, 'normal', '2025-11-04 18:18:01', '2025-11-28 15:22:17', 90, 1, '2025-11-14 19:35:53', NULL, 0, 0, NULL, 0, 0, 0),
(54, 'Configuração de usuários. Realocação', 'Prezados,\r\n\r\nSolicito providenciar as configurações para os devidos usuários:\r\n\r\n  * Carlos Eduardo: Perfil SEI, BRC e Storage para Cobrança\r\n  * Célia: Perfil SEI, BRC e Storage para Cadastro\r\n  * Renata: Perfil SEI, BRC e Storage para COE e Ouvidoria.\r\n\r\nAtenciosamente,\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	Marcelo Borges Teixeira\r\nCoordenador Financeiro\r\nmarcelo.teixeira@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 5, 'marcelo.teixeira@crprs.org.br', 1, 'encerrado', NULL, 'normal', '2025-11-04 19:04:01', '2025-11-28 15:22:17', 46, 1, '2025-11-07 15:03:02', NULL, 0, 0, NULL, 0, 0, 0),
(55, 'SISCONT', 'Boa tarde, Rafael.\r\n\r\nIniciamos um teste no SISCONT, hoje a tarde, estamos enfrentando alguns \r\nproblemas para dar andamento no processo. Amanhã, vamos nos reunir \r\nnovamente, no primeiro horário. Vamos precisar de um suporte, podes nos \r\najudar?\r\n\r\nAtt.,\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	Keli Rossi\r\nFinanceiro\r\nkeli.rossi@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 16, 'keli.rossi@crprs.org.br', 2, 'encerrado', NULL, 'normal', '2025-11-04 20:02:01', '2025-11-28 15:22:17', 84, 2, '2025-11-06 17:40:56', NULL, 0, 0, NULL, 0, 0, 0),
(56, 'E-mail', 'Prezada(o), bom dia!\r\nSolicito a retirar do direcionamento de e-mail da danuza.daudt@.\r\n\r\nAt.te,\r\n\r\n\r\n	Hanna Paula Biskup Fagundes\r\nSupervisora do Setor de Cadastro\r\nhanna.fagundes@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 11, 'hanna.fagundes@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-11-05 12:04:01', '2025-11-28 15:22:17', 31, 3, '2025-11-05 12:28:32', NULL, 0, 0, NULL, 0, 0, 0),
(57, 'Instalação de segundo monitor', 'Mateus, por favor, instale um segundo monitor para a Renata da COE', 1, 'hugo.miranda@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-11-05 12:42:33', '2025-11-28 15:22:17', 4, 3, '2025-11-05 14:04:32', NULL, 0, 0, NULL, 0, 0, 0),
(58, 'Instalação de computador ', 'Mateus, por gentileza, instale um computador (com 2 monitores) novo para a Michele (advogada).\r\nSegue Orientações:\r\n\r\nCONFIGURAÇÕES DOS MINI PC’S DELL \r\n- Colocar no Domínio.\r\n- Alterar nome do PC.\r\n- Colocar na descrição o número do Patrimonio e setor.\r\n\r\n\r\nINSTALAR\r\n - Adobe Reader\r\n- Chrome\r\n- Thunderbird\r\n- Sophos Endpoint\r\n- Zoom\r\n- Office 365\r\n', 1, 'hugo.miranda@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-11-05 12:46:40', '2025-11-28 15:22:17', 5, 3, '2025-11-06 14:10:14', NULL, 0, 0, NULL, 0, 0, 0),
(59, 'E-mail processo@', 'Bom dia, colegas.\r\n\r\nPor gentileza, é possível que o e-mail processo@ entre no Thunderbird da \r\nnova Assistente Administrativa que acompanhará a COE, Renata?\r\n\r\nObrigada.\r\n\r\nAtenciosamente.\r\n\r\n	Flávia Cardozo de Mattos\r\nCoordenadora Técnico-Política\r\nCRP 07/15863\r\nflavia.mattos@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 14, 'flavia.mattos@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-11-05 13:16:01', '2025-11-28 15:22:17', 31, 3, '2025-11-06 14:20:26', NULL, 0, 0, NULL, 0, 0, 0),
(60, 'E-mail - cadastro4', 'Prezada(o), bom dia!\r\nSolicito a retirar do direcionamento de e-mail da cadastro4@\r\n\r\n\r\nAt.te,\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	Hanna Paula Biskup Fagundes\r\nSupervisora do Setor de Cadastro\r\nhanna.fagundes@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 11, 'hanna.fagundes@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-11-05 13:34:01', '2025-11-28 15:22:17', 31, 3, '2025-11-05 14:06:05', NULL, 0, 0, NULL, 0, 0, 0),
(61, 'SISCAF', 'Prezada(o), bom dia!\r\nAbri alguns chamados no Gesti para atualizar os históricos de situações, \r\ne foi solicitado um print do SISCAF. Porém, não tenho acesso ao sistema.\r\n\r\n\r\n\r\nAt.te,\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	Hanna Paula Biskup Fagundes\r\nSupervisora do Setor de Cadastro\r\nhanna.fagundes@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br\n\n📎 1 anexo(s) do email foram salvos.', 11, 'hanna.fagundes@crprs.org.br', 1, 'aguardando_terceiros', NULL, 'normal', '2025-11-05 14:46:01', '2025-11-28 15:22:17', 89, NULL, NULL, NULL, 0, 0, NULL, 0, 0, 0),
