INSERT INTO `tickets` (`id`, `titulo`, `descricao`, `usuario_id`, `email_solicitante`, `agente_id`, `status`, `status_anterior`, `prioridade`, `criado_em`, `atualizado_em`, `categoria_id`, `fechado_por`, `fechado_em`, `tempo_primeiro_atendimento`, `tempo_total_segundos`, `tempo_em_espera_segundos`, `iniciou_espera_em`, `tem_comentario_nao_lido`, `reaberto_contador`, `sla_vencido`) VALUES
(74, 'Re: CADASTRO CRP RS', 'Prezada(o), boa tarde!\r\n\r\nQuando o protocolo estava aberto, era necessário responder aos e-mails \r\nencaminhados pelo colega do endereço caxias@crprs.org.br.\r\n\r\nAgora, será necessário encaminhar toda a documentação novamente, em um \r\nnovo processo, com cópia para o setor de *TI*, a fim de que seja \r\nliberado o acesso ao formulário de inscrição de Pessoa Jurídica.\r\n\r\nCNPJ: 61.249.491/0001-01\r\n\r\nAt.te,\r\n\r\nDocumento sem título\r\n\r\n	Hanna Paula Biskup Fagundes\r\nSupervisora do Setor de Cadastro\r\nhanna.fagundes@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br\r\n\r\nEm 06/11/2025 17:06, Labrêa Assessoria escreveu:\r\n> Mas como faço para anexar documentos ? porque ali nao tem opçoes para \r\n> anexar teria como me passa um passo a passo\r\n>\r\n>\r\n>\r\n>\r\n> Em qui., 6 de nov. de 2025 às 16:51, Conselho Regional de Psicologia \r\n> do RS - Cadastro  escreveu:\r\n>\r\n>     Prezada(o), boa tarde!\r\n>\r\n>     Em 20/10, foi informado que o Termo de Ciência não estava assinado\r\n>     pela sócia/proprietária, e até o momento não recebemos o retorno\r\n>     com o documento devidamente assinado.\r\n>\r\n>     Dessa forma, a solicitação de inscrição da Pessoa Jurídica foi\r\n>     indeferida.\r\n>\r\n>\r\n>\r\n>     At.te,\r\n>\r\n>\r\n>     	Hanna Paula Biskup Fagundes\r\n>     Supervisora do Setor de Cadastro\r\n>     hanna.fagundes@crprs.org.br\r\n>\r\n>     Conselho Regional de Psicologia do Rio Grande do Sul\r\n>     Av. Protásio Alves, 2854/301\r\n>     Porto Alegre/RS\r\n>     (51) 3334.6799\r\n>     www.crprs.org.br \r\n>\r\n>     Em 06/11/2025 15:04, Labrêa Assessoria escreveu:\r\n>>     Prezada boa tarde!\r\n>>\r\n>>     Precisamos de orientação, pois seguimos os passos de requerimento\r\n>>     eletrônico e não foi solictado nenhum documento:\r\n>>\r\n>>     image.png\r\n>>\r\n>>\r\n>>\r\n>>\r\n>>     Em qua., 5 de nov. de 2025 às 13:37, Conselho Regional de\r\n>>     Psicologia do RS - Cadastro  escreveu:\r\n>>\r\n>>         Prezada(o), boa tarde!\r\n>>         Em relação ao pedido de inscrição, informamos que o mesmo foi\r\n>>         indeferido devido à não apresentação dos documentos solicitados.\r\n>>\r\n>>         Uma nova solicitação poderá ser apresentada através do site\r\n>>         do Conselho, em\r\n>>         https://crprs.org.br/servicos/servicos-para-pessoa-juridica\r\n>>\r\n>>\r\n>>         À disposição\r\n>>\r\n>>         At.te,\r\n>>\r\n>>\r\n>>         	Hanna Paula Biskup Fagundes\r\n>>         Supervisora do Setor de Cadastro\r\n>>         hanna.fagundes@crprs.org.br\r\n>>\r\n>>         Conselho Regional de Psicologia do Rio Grande do Sul\r\n>>         Av. Protásio Alves, 2854/301\r\n>>         Porto Alegre/RS\r\n>>         (51) 3334.6799\r\n>>         www.crprs.org.br \r\n>>\n\n📎 1 anexo(s) do email foram salvos.', 21, 'cadastro@crprs.org.br', 1, 'encerrado', NULL, 'normal', '2025-11-06 20:20:02', '2025-11-28 15:22:17', 10, 1, '2025-11-19 17:25:17', NULL, 0, 0, NULL, 0, 0, 0),
(75, 'E-mails comissoes@ e jordan.mello@', 'Boa tarde.\r\n\r\nPor gentileza, preciso que verifiquem no histórico de e-mails das \r\ncomissões e do Jordan se há algum registro de estudo relativo ao \r\nmunicípio de Frederico Westphalen. Esse estudo teria ocorrido em um \r\nGrupo de Trabalho formado entre Comissão de Avaliação Psicológica e \r\nComissão de Educação.\r\n\r\nObrigada.\r\n\r\n\r\n	Flávia Cardozo de Mattos\r\nCoordenadora Técnico-Política\r\nCRP 07/15863\r\nflavia.mattos@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 14, 'flavia.mattos@crprs.org.br', 1, 'encerrado', NULL, 'normal', '2025-11-06 21:02:01', '2025-11-28 15:22:17', 31, 1, '2025-11-17 14:33:36', NULL, 0, 0, NULL, 0, 0, 0),
(76, 'Re: CARPE', 'Boa tarde.\r\n\r\nInclusão da Assistente Administrativa Cristina também, por gentileza.\r\n\r\nDocumento sem título\r\n\r\n	Flávia Cardozo de Mattos\r\nCoordenadora Técnico-Política\r\nCRP 07/15863\r\nflavia.mattos@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br\r\n\r\nEm 04/11/2025 14:44, Conselho Regional de Psicologia do RS - Flavia \r\nCardozo de Mattos escreveu:\r\n>\r\n> Boa tarde colegas.\r\n>\r\n> Ao setor de TI, solicito inclusão das Fiscais Kwala e Letícia na CARPE \r\n> (SEi e BRC), conforme portaria anexa, bem como das Conselheiras Esther \r\n> Abigail Helena Maciel Nunes e Vanessa Arlete Marques Cazelato.\r\n>\r\n> À Assistente Administrativa Cristina, solicito que distribua \r\n> igualmente os processos da CARPE entre os Fiscais portariados.\r\n>\r\n> Aos Fiscais, seguimos fazendo as combinações necessárias em reunião.\r\n>\r\n> Agradeço desde já.\r\n>\r\n> Atenciosamente.\r\n>\r\n>\r\n> 	Flávia Cardozo de Mattos\r\n> Coordenadora Técnico-Política\r\n> CRP 07/15863\r\n> flavia.mattos@crprs.org.br\r\n>\r\n> Conselho Regional de Psicologia do Rio Grande do Sul\r\n> Av. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n> (51) 3334.6799\r\n> www.crprs.org.br\r\n>', 14, 'flavia.mattos@crprs.org.br', NULL, 'encerrado', NULL, 'normal', '2025-11-06 21:06:01', '2025-11-28 15:22:17', 72, 1, '2025-11-07 11:16:49', NULL, 0, 0, NULL, 0, 0, 0),
(77, 'Inclusão_de_usuário_na_Unidade_SEI_-_07/CAD', 'Bom dia,\r\n\r\nFavor incluir a assistente administrativa CELIA VITT MEKSRAITIS na \r\nunidade 07/CAD.\r\n\r\nObrigado.\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	André Sommer Bertão\r\nCoordenador Administrativo\r\nandre.bertao@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 6, 'andre.bertao@crprs.org.br', 1, 'encerrado', NULL, 'normal', '2025-11-07 11:14:01', '2025-11-28 15:22:17', 11, 1, '2025-11-07 11:20:06', NULL, 0, 0, NULL, 0, 0, 0),
(78, 'e-mail cadastro 5', 'Prezada(o), boa tarde!\r\nPor gentileza, solicito a retirada direcionamento de e-mail da cadastro5@.\r\n\r\nAt.te,\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	Hanna Paula Biskup Fagundes\r\nSupervisora do Setor de Cadastro\r\nhanna.fagundes@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 11, 'hanna.fagundes@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-11-07 15:24:01', '2025-11-28 15:22:17', 31, 3, '2025-11-07 15:38:19', NULL, 0, 0, NULL, 0, 0, 0),
(79, 'ACESSO THUNDERBIRD NOTEBOOK', 'Boa tarde!\r\n\r\nSolicito ajuda para baixar o aplicativo Thunderbird no notebook que me \r\nemprestaram.\r\n\r\n\r\nAtenciosamente\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	Guilherme Bernst Roesler\r\nCoordenador de Comunicação\r\nguilherme.roesler@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 7, 'guilherme.roesler@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-11-07 16:56:01', '2025-11-28 15:22:17', 31, 3, '2025-11-17 12:35:11', NULL, 0, 0, NULL, 0, 0, 0),
(80, 'Inclusão de endereços de e-mail na unidade 07-CCOM', 'Verificar os usuarios cadastrados na unidade 07-CCOM e solicitar ao CFP a inclusão dos respectivos endereços de e-mail.\r\nObs.: Informar ao CFP somente os e-mails institucionais.', 10, 'nadia.miola@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-11-10 11:44:35', '2025-11-28 15:22:17', 11, 3, '2025-11-11 13:13:34', NULL, 0, 0, NULL, 0, 0, 0),
(81, 'Notebook Assistente Administrativa COE', 'Bom dia.\r\n\r\nPor gentileza, se houver equipamento disponível, seria importante que a \r\nAssistente Administrativa que auxilia a Comissão de Ética, Renata \r\nSevergnini, dispusesse de um notebook, uma vez que sua rotina inclui \r\nreuniões fora de sua estação de trabalho.\r\n\r\nAgradeço desde já e permaneço à disposição.\r\n\r\nAtenciosamente.\r\n\r\n	Flávia Cardozo de Mattos\r\nCoordenadora Técnico-Política\r\nCRP 07/15863\r\nflavia.mattos@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 14, 'flavia.mattos@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-11-10 13:02:01', '2025-11-28 15:22:17', 6, 3, '2025-11-12 14:12:27', NULL, 0, 0, NULL, 0, 0, 0),
(82, 'Telefone', 'Prezada(o), bom dia!\r\n\r\nPor gentileza, solicitamos a instalação de um telefone na mesa da Elisa.\r\n\r\n\r\nAt.te,\r\n\r\nDocumento sem título\r\n\r\n	Hanna Paula Biskup Fagundes\r\nSupervisora do Setor de Cadastro\r\nhanna.fagundes@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 11, 'hanna.fagundes@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-11-10 13:14:01', '2025-11-28 15:22:17', 3, 3, '2025-11-10 14:31:14', NULL, 0, 0, NULL, 0, 0, 0),
(83, 'Site IDG', 'Solicito a liberação do site http://idgrs.com.br\r\n\r\nGrata!\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	Aline Victorino\r\nAssessora de Comunicação\r\nJornalista - Mtb 11602\r\nalinevictorino@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 17, 'aline.victorino@crprs.org.br', 1, 'encerrado', NULL, 'normal', '2025-11-10 14:10:02', '2025-11-28 15:22:17', 35, 1, '2025-11-10 14:40:00', NULL, 0, 0, NULL, 0, 0, 0),
(84, 'Instalação de computadores novos.', 'Instalar computado novo para a Fiscal Leticia Giannechini na tarde desta segunda a partir das 13h30, enquanto ela está na reunião da COF.\r\nInstalar computador novo para a Raquel (Cadastro) assim que possível. Combinar com ela melhor horário.', 1, 'hugo.miranda@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-11-10 14:33:18', '2025-11-28 15:22:17', 5, 3, '2025-11-13 17:29:02', NULL, 0, 0, NULL, 0, 0, 0),
(85, 'Inclusão', 'Prezada(o), boa tarde!\r\n\r\nSolicito a inclusão dos remetentes cadastro - Hanna, Jean, Danuza e \r\nCélia pra envio de e-mail.\r\n\r\n\r\nAt.te,\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	Hanna Paula Biskup Fagundes\r\nSupervisora do Setor de Cadastro\r\nhanna.fagundes@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br\n\n📎 1 anexo(s) do email foram salvos.', 11, 'hanna.fagundes@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-11-10 16:10:02', '2025-11-28 15:22:17', 11, 3, '2025-11-11 14:07:28', NULL, 0, 0, NULL, 0, 0, 0),
(86, 'Email presidencia@', 'Boa tarde, Hugo.\r\n\r\nEstamos com uma dificuldade com o e-mail presidencia@. As denúncias \r\nsempre são remetidas para presidencia@, orientec@ e flavia.mattos@. No \r\nentanto, para a Presidenta, só aparece o presidencia@ como destinatário. \r\nNossa dificuldade é que o recurso \"responder a todos\", que utilizamos \r\nmuito, não fica disponível para a Presidenta. Podes nos auxiliar a \r\nverificar se é alguma configuração?\r\n\r\nMuito obrigada.\r\n\r\nAtenciosamente.\r\n\r\n	Flávia Cardozo de Mattos\r\nCoordenadora Técnico-Política\r\nCRP 07/15863\r\nflavia.mattos@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 14, 'flavia.mattos@crprs.org.br', 1, 'encerrado', NULL, 'normal', '2025-11-10 20:54:01', '2025-11-28 15:22:17', 31, 1, '2025-11-11 13:10:13', NULL, 0, 0, NULL, 0, 0, 0),
(87, 'Liberação_Vinicius_Larratea_à_pasta_Retorno_de_D01-SEFIN', 'Bom dia ,\r\n\r\nfavor proceder com a liberação de acesso para o funcionário Vinicius \r\nLarratea à pasta Retorno (dos arquivos bancários) do D01-SEFIN.\r\n\r\nFico no aguardo.\r\n\r\nAt.te,\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	Marcia Cristina Silveira de Castro\r\nSupervisora do Setor de Cobrança\r\nmarcia.castro@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 18, 'marcia.castro@crprs.org.br', 1, 'encerrado', NULL, 'normal', '2025-11-11 11:42:02', '2025-11-28 15:22:17', 46, 1, '2025-11-11 14:04:54', NULL, 0, 0, NULL, 0, 0, 0),
(88, 'configuração de e-mail ouvidoria@crprs.org.br', 'Configurar e-mail ouvidoria@crprs.org.br no Thunderbird da Renata. \r\nPasta: Storage >> Emails >> E-mails Ouvidoria\r\nAssinatura >> Storage >> Temporario >> Assianatura de e-mails >> Ouvidoria.', 1, 'hugo.miranda@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-11-11 12:19:01', '2025-11-28 15:22:17', 31, 3, '2025-11-12 13:43:35', NULL, 0, 0, NULL, 0, 0, 0),
(176, 'Fwd: [CRPRS] Etapa 2 - Sala Pelotas', 'Hugo / Matheus\r\n\r\nNão estou conseguindo extrair os docs do arquivo em anexo. Não localizei \r\n7-zip ou WinRar no meu pc para extrair os arquivos.\r\n\r\nPeço, por gentileza, auxílio.\r\n\r\nDocumento sem título\r\n\r\n	Marcelo Borges Teixeira\r\nCoordenador Financeiro\r\nmarcelo.teixeira@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br\r\n\r\n\r\n\r\n-------- Mensagem encaminhada --------\r\nAssunto: 	Re: [CRPRS] Etapa 2 - Sala Pelotas\r\nData: 	Mon, 10 Nov 2025 16:25:51 -0300\r\nDe: 	Abra - Preservação do Patrimônio Cultural \r\nPara: 	Conselho Regional de Psicologia do RS - Marcelo Borges Teixeira \r\n\r\nCC: 	Conselho Regional de Psicologia do RS - Rafael Gustavo Rueda \r\n\r\n\r\n\r\n\r\nOlá, boa tarde,\r\n\r\nPrezados,\r\n\r\nVenho através deste entregar a prancha com as imagens renderizadas após \r\nos últimos ajustes solicitados na reunião do dia 20/10.\r\nSalientamos que, devido a um conflito entre a nova cadeira e a mesa da \r\nsala de atendimento administrativo, a mesa teve de ser alterada, por \r\nisso, todas as pranchas em PDF e arquivos em CAD foram alterados.\r\nTodas essas atualizações se encontram no arquivo ZIPADO de nome \r\n/ABRA-CRPRS-PROJETOS-MEMORIAL./ Já o arquivo zipado da entrega, por \r\ne-mail, da semana passada intitulado de \r\n/ABRA-CRP-ORÇAMENTO-CRONOGRAMA-MATERIAIS/, não precisou ser atualizado e \r\npor isso não deve ser substituído.\r\nFicamos no aguardo da confirmação do recebimento.\r\n\r\nEm qua., 5 de nov. de 2025 às 16:46, Conselho Regional de Psicologia do \r\nRS - Marcelo Borges Teixeira  escreveu:\r\n\r\n\r\n    Perfeito,\r\n\r\n    Grato pelo pronto retorno.\r\n\r\n    Atenciosamente,\r\n\r\n\r\n    	Marcelo Borges Teixeira\r\n    Coordenador Financeiro\r\n    marcelo.teixeira@crprs.org.br\r\n\r\n    Conselho Regional de Psicologia do Rio Grande do Sul\r\n    Av. Protásio Alves, 2854/301\r\n    Porto Alegre/RS\r\n    (51) 3334.6799\r\n    www.crprs.org.br \r\n\r\n    Em 05/11/2025 16:27, Abra - Preservação do Patrimônio Cultural escreveu:\r\n>     Olá, boa tarde,\r\n>\r\n>     Prezados,\r\n>\r\n>     Entendemos a situação de vocês, entretanto modificações, mesmo que\r\n>     pequenas, alteram bastante os detalhamentos. Tentaremos entregar o\r\n>     3D o mais breve possível na semana que vem.\r\n>\r\n>     Em qua., 5 de nov. de 2025 às 14:26, Conselho Regional de\r\n>     Psicologia do RS - Marcelo Borges Teixeira\r\n>      escreveu:\r\n>\r\n>\r\n>         Prezadas,\r\n>\r\n>         Para fins de composição do Edital de licitação, necessitaremos\r\n>         do layout da etapa anterior atualizada para a devida\r\n>         divulgação do processo de contratação.\r\n>\r\n>         Peço, por gentileza, verificar a viabilidade de realizar a\r\n>         entrega até o final desta semana, assim providenciaremos o\r\n>         pagamento da etapa 2 até para a terça-feira, dia 11.\r\n>\r\n>         Atenciosamente,\r\n>\r\n>\r\n>         	Marcelo Borges Teixeira\r\n>         Coordenador Financeiro\r\n>         marcelo.teixeira@crprs.org.br\r\n>\r\n>         Conselho Regional de Psicologia do Rio Grande do Sul\r\n>         Av. Protásio Alves, 2854/301\r\n>         Porto Alegre/RS\r\n>         (51) 3334.6799\r\n>         www.crprs.org.br \r\n>\r\n>         Em 05/11/2025 13:28, Abra - Preservação do Patrimônio Cultural\r\n>         escreveu:\r\n>>         Prezados,\r\n>>\r\n>>         As imagens em 3D faziam parte somente da etapa anterior já\r\n>>         finalizada e já paga, por isso não foram realizadas para\r\n>>         essas últimas alterações.\r\n>>         Entretanto, podemos atualizar a maquete eletrônica e entregar\r\n>>         o PDF até o final da semana que vem.\r\n>>         Ficamos no aguardo da resposta de vocês.\r\n>>\r\n>>         Em qua., 5 de nov. de 2025 às 10:30, Conselho Regional de\r\n>>         Psicologia do RS - Marcelo Borges Teixeira\r\n>>          escreveu:\r\n>>\r\n>>\r\n>>             Prezadas,\r\n>>\r\n>>             Grato pela entrega.\r\n>>\r\n>>             Não localizamos o layout da sala em 3D com as alterações\r\n>>             em PDF.\r\n>>\r\n>>             Poderia verificar e realizar o envio?\r\n>>\r\n>>             Atenciosamente,\r\n>>\r\n>>\r\n>>             	Marcelo Borges Teixeira\r\n>>             Coordenador Financeiro\r\n>>             marcelo.teixeira@crprs.org.br\r\n>>\r\n>>             Conselho Regional de Psicologia do Rio Grande do Sul\r\n>>             Av. Protásio Alves, 2854/301\r\n>>             Porto Alegre/RS\r\n>>             (51) 3334.6799\r\n>>             www.crprs.org.br \r\n>>\r\n>>             Em 05/11/2025 08:00, Abra - Preservação do Patrimônio\r\n>>             Cultural escreveu:\r\n>>>             Olá, bom dia,\r\n>>>\r\n>>>             Prezados,\r\n>>>\r\n>>>             Estamos enviando a entrega solicitada em reunião (dia\r\n>>>             20/10), com a pauta /Ajuste Final do Projeto./\r\n>>>             A seguir, no formato zipado, encontra-se os arquivos\r\n>>>             /ABRA-CRP-ORÇAMENTO-CRONOGRAMA-MATERIAIS/, com arquivos\r\n>>>             referentes ao nome do documento, mais anexos e\r\n>>>             /ABRA-CRP-PROJETOS-MEMORIAL/, com os arquivos da\r\n>>>             atualização do projeto arquitetônico, complementares e\r\n>>>             de detalhamento do mobiliário, em PDF e em CAD e o\r\n>>>             memorial descritivo.\r\n>>>             Ficamos no aguardo da confirmação do recebimento\r\n>>>\r\n>>>             Em qui., 30 de out. de 2025 às 11:05, Conselho Regional\r\n>>>             de Psicologia do RS - Marcelo Borges Teixeira\r\n>>>              escreveu:\r\n>>>\r\n>>>\r\n>>>                 Perfeito.\r\n>>>\r\n>>>                 Ok para alteração.\r\n>>>\r\n>>>                 Atenciosamente,\r\n>>>\r\n>>>\r\n>>>                 	Marcelo Borges Teixeira\r\n>>>                 Coordenador Financeiro\r\n>>>                 marcelo.teixeira@crprs.org.br\r\n>>>\r\n>>>                 Conselho Regional de Psicologia do Rio Grande do Sul\r\n>>>                 Av. Protásio Alves, 2854/301\r\n>>>                 Porto Alegre/RS\r\n>>>                 (51) 3334.6799\r\n>>>                 www.crprs.org.br \r\n>>>\r\n>>>                 Em 30/10/2025 11:03, Abra - Preservação do\r\n>>>                 Patrimônio Cultural escreveu:\r\n>>>>                 Prezados,\r\n>>>>\r\n>>>>                 Em relação ao último termo do parecer \"Ajuste Final\r\n>>>>                 do projeto - verificar a viabilidade de substituir\r\n>>>>                 a cadeira para foto dos profissionais\". Temos a\r\n>>>>                 solução se inserir no espaço mais uma cadeira para\r\n>>>>                 obeso e na parede instalar um suporte para fundo\r\n>>>>                 fotográfico.\r\n>>>>                 Ficamos no aguardo do \"ok\" de vocês para alterarmos\r\n>>>>                 no projeto.\r\n>>>>\r\n>>>>                 Em ter., 28 de out. de 2025 às 17:01, Conselho\r\n>>>>                 Regional de Psicologia do RS - Marcelo Borges\r\n>>>>                 Teixeira  escreveu:\r\n>>>>\r\n>>>>\r\n>>>>                     Prezadas,\r\n>>>>\r\n>>>>                     Contatei há pouco o Arquiteto e ele informou\r\n>>>>                     possuir uma limitação de liberações.\r\n>>>>\r\n>>>>                     Segue link\r\n>>>>                     do\r\n>>>>                     drive para acesso ao projeto.\r\n>>>>\r\n>>>>                     Qualquer dúvida, permaneço à disposição.\r\n>>>>\r\n>>>>                     Atenciosamente,\r\n>>>>\r\n>>>>\r\n>>>>                     	Marcelo Borges Teixeira\r\n>>>>                     Coordenador Financeiro\r\n>>>>                     marcelo.teixeira@crprs.org.br\r\n>>>>\r\n>>>>                     Conselho Regional de Psicologia do Rio Grande\r\n>>>>                     do Sul\r\n>>>>                     Av. Protásio Al