(190, 'Solicitação_de_acesso_-_Sistema_Thomas_Greg', 'Prezados,\r\n\r\nPeço liberação de acesso aos sistemas Sig Cip e CAV.\r\n\r\nSegue documentação comprovando vínculo com o Conselho.\r\n\r\nObrigado.\r\n\r\n\r\nAtenciosamente,\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	André Sommer Bertão\r\nCoordenador Administrativo\r\nandre.bertao@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br\n\n📎 2 anexo(s) do email foram salvos.', 6, 'andre.bertao@crprs.org.br', 1, 'encerrado', NULL, 'normal', '2025-11-18 16:32:30', '2025-12-02 12:49:45', 90, 1, '2025-12-02 12:49:45', NULL, 0, 0, NULL, 0, 0, 0),
(191, 'inclusão_no_atendimento@', 'Prezada(o), boa tarde!\r\nFavor incluir a Célia no e-mail do atendimento@\r\n\r\nAt.te,\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	Hanna Paula Biskup Fagundes\r\nSupervisora do Setor de Cadastro\r\nhanna.fagundes@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 21, 'cadastro@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-11-18 19:50:02', '2025-11-28 15:22:17', 31, 3, '2025-11-19 17:12:59', NULL, 0, 0, NULL, 0, 0, 0),
(192, 'desligamento_funcionária_MICHELE', 'Bom dia,\r\n\r\nInformo que a funcionária MICHELE não faz mais parte do quadro de \r\nfuncionários a partir de hoje\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	Elizandra Caprini\r\nSupervisora de Recursos Humanos\r\nCRCRS-082296/O-0\r\nrh@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301 - Porto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 30, 'rh@crprs.org.br', 1, 'encerrado', NULL, 'normal', '2025-11-19 10:23:28', '2025-11-28 15:22:17', 46, 1, '2025-11-19 17:24:24', NULL, 0, 0, NULL, 0, 0, 0),
(193, 'Acesso_ao_site_para_inclusão_do_título_de_especialista', 'Bom dia,\r\n\r\ntentei acessar o site do CFP para incluir o título de especialista, mas \r\napareceu essa mensagem.\r\n\r\n\r\nAt.te,\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	Hanna Paula Biskup Fagundes\r\nSupervisora do Setor de Cadastro\r\nhanna.fagundes@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br\n\n📎 1 anexo(s) do email foram salvos.', 11, 'hanna.fagundes@crprs.org.br', 1, 'encerrado', NULL, 'normal', '2025-11-19 13:35:27', '2025-12-12 14:29:31', 67, 1, '2025-12-12 14:29:31', NULL, 0, 0, NULL, 0, 0, 0),
(194, 'redirecionamento de e-mails raquel.lopes', 'Bom dia,\r\n\r\nSolicito cópia dos e-mails enviados para o endereço \r\n*raquel.lopes**@* para a minha caixa de entrada, *no período de 19/11, a \r\npartir das **17h*, durante as férias da colega Raquel até 01/12 às 8h.\r\n\r\n\r\nAt.te,\r\n\r\n\r\n	Hanna Paula Biskup Fagundes\r\nSupervisora do Setor de Cadastro\r\nhanna.fagundes@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br', 21, 'cadastro@crprs.org.br', 3, 'encerrado', NULL, 'normal', '2025-11-19 14:10:02', '2025-12-01 12:12:06', 31, 3, '2025-12-01 12:12:06', NULL, 0, 0, NULL, 0, 0, 0),
