(196, 'Lembrete:_É_hora_de_alterar_a_senha_:)', 'Email Locaweb\r\n    \r\n    \r\n    \r\n      .col-left{\r\n        text-align: left;\r\n      }\r\n      .col-right{\r\n        text-align: right;\r\n      }\r\n      @media screen and (max-width: 525px) {\r\n        .he-wrapper {\r\n          width: 100% !important;\r\n          max-width: 100% !important;\r\n        }\r\n        .logo img {\r\n          margin: 0 auto !important;\r\n        }\r\n        .mobile-hide {\r\n          display: none !important;\r\n        }\r\n        .img-max {\r\n          max-width: 100% !important;\r\n          width: 100% !important;\r\n          height: auto !important;\r\n        }\r\n        .responsive-table {\r\n          width: 100% !important;\r\n        }\r\n        .padding {\r\n          padding: 10px 5% 15px 5% !important;\r\n        }\r\n        .padding-meta {\r\n          padding: 30px 5% 0px 5% !important;\r\n          text-align: center;\r\n        }\r\n        .padding-copy {\r\n          padding: 10px 5% 10px 5% !important;\r\n          text-align: center;\r\n        }\r\n        .no-padding {\r\n          padding: 0 !important;\r\n        }\r\n        .section-padding {\r\n          padding: 50px 15px 50px 15px !important;\r\n        }\r\n        .mobile-button-container {\r\n          margin: 0 auto;\r\n          width: 100% !important;\r\n        }\r\n        .mobile-button {\r\n          padding: 15px !important;\r\n          border: 0 !important;\r\n          font-size: 16px !important;\r\n          display: block !important;\r\n        }\r\n        .he-col {\r\n          min-width: 100% !important;\r\n        }\r\n        .col-left, .col-right{\r\n          text-align: center !important;\r\n        }\r\n        .col-left table, .col-right table{\r\n          display: inline !important;\r\n          width: initial !important;\r\n        }\r\n        .step-by-step-left, .step-by-step-right, .featured-special-box-left, .featured-special-box-right {\r\n        