(232, '43692_-_acesso_ao_site_para_emissão_de_certidão', 'Prezada(o), bom dia!\r\nTentei alterar a senha da profissional, realizei o teste e não consegui \r\nacessar, aparece a mensagem abaixo.\r\n\r\nSenha: 43692dns\r\n\r\n\r\nAt.te,\r\n\r\n-- \r\nDocumento sem título\r\n\r\n	Hanna Paula Biskup Fagundes\r\nSupervisora do Setor de Cadastro\r\nhanna.fagundes@crprs.org.br\r\n\r\nConselho Regional de Psicologia do Rio Grande do Sul\r\nAv. Protásio Alves, 2854/301\r\nPorto Alegre/RS\r\n(51) 3334.6799\r\nwww.crprs.org.br\n\n📎 1 anexo(s) do email foram salvos.', 21, NULL, 3, 'encerrado', NULL, 'normal', '2025-12-02 14:40:03', '2025-12-02 14:57:52', 10, 3, '2025-12-02 14:57:52', NULL, 0, 0, NULL, 0, 0, 0),
